import { useState } from 'react';
import { toast } from 'sonner';
import {
  Upload,
  RefreshCw,
  Loader2,
  Eye,
  Edit2,
  GripVertical,
  Clock,
  CheckCircle2,
  Package,
  Zap,
  Star,
  Heart,
  Shield,
  Award,
  ThumbsUp,
  Lightbulb,
  Settings,
  TrendingUp,
  Check,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import {
  Select,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectItem,
} from '@/components/ui/select';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import SyncStatusBadge from '@/components/SyncStatusBadge';
import { useQuoteSection, type IQuoteFeature } from '@/hooks/useQuoteSection';
import { useI18n } from '@/i18n/I18nContext';
import { createI18nText, type I18nText } from '@/lib/i18n-text';
import { useSyncService } from '@/context/SyncServiceContext';
import { batchTranslateI18n } from '@/lib/translate';

const ICON_OPTIONS = [
  { value: 'Clock', label: 'Clock', Icon: Clock },
  { value: 'CheckCircle2', label: 'Check Circle', Icon: CheckCircle2 },
  { value: 'Package', label: 'Package', Icon: Package },
  { value: 'Zap', label: 'Zap', Icon: Zap },
  { value: 'Star', label: 'Star', Icon: Star },
  { value: 'Heart', label: 'Heart', Icon: Heart },
  { value: 'Shield', label: 'Shield', Icon: Shield },
  { value: 'Award', label: 'Award', Icon: Award },
  { value: 'ThumbsUp', label: 'Thumbs Up', Icon: ThumbsUp },
  { value: 'Lightbulb', label: 'Lightbulb', Icon: Lightbulb },
  { value: 'Settings', label: 'Settings', Icon: Settings },
  { value: 'TrendingUp', label: 'Trending Up', Icon: TrendingUp },
  { value: 'Check', label: 'Check', Icon: Check },
];

function getIconComponent(name: string) {
  const map: Record<string, React.ComponentType<{ className?: string }>> = {
    Clock,
    CheckCircle2,
    Package,
    Zap,
    Star,
    Heart,
    Shield,
    Award,
    ThumbsUp,
    Lightbulb,
    Settings,
    TrendingUp,
    Check,
  };
  return map[name] || CheckCircle2;
}

type Lang = 'en' | 'zh' | 'es' | 'ja';

export default function AdminQuoteSectionPage() {
  const { adminT, language } = useI18n();
  const { quoteSection, saveQuoteSection, setShowOnHomepage } = useQuoteSection();
  const { markDirty, syncJsonFile, getStatus, getGithubApiConfig } = useSyncService();
  const syncStatus = getStatus('quoteSection');
  const [pageTranslating, setPageTranslating] = useState(false);
  const [pageProgress, setPageProgress] = useState({ current: 0, total: 0 });
  const [activeLang, setActiveLang] = useState<Lang>('en');

  const handleTitleChange = (lang: Lang, value: string) => {
    const next = {
      ...quoteSection,
      title: { ...quoteSection.title, [lang]: value },
    };
    saveQuoteSection(next);
    markDirty('quoteSection');
  };

  const handleSubtitleChange = (lang: Lang, value: string) => {
    const next = {
      ...quoteSection,
      subtitle: { ...quoteSection.subtitle, [lang]: value },
    };
    saveQuoteSection(next);
    markDirty('quoteSection');
  };

  const handleFeatureTextChange = (id: string, lang: Lang, value: string) => {
    const nextFeatures = quoteSection.features.map((f) =>
      f.id === id ? { ...f, text: { ...f.text, [lang]: value } } : f
    );
    saveQuoteSection({ ...quoteSection, features: nextFeatures });
    markDirty('quoteSection');
  };

  const handleFeatureIconChange = (id: string, icon: string) => {
    const nextFeatures = quoteSection.features.map((f) =>
      f.id === id ? { ...f, icon } : f
    );
    saveQuoteSection({ ...quoteSection, features: nextFeatures });
    markDirty('quoteSection');
  };

  const addFeature = () => {
    const newFeature: IQuoteFeature = {
      id: `f_${Date.now()}`,
      icon: 'CheckCircle2',
      text: createI18nText('New feature', '新特点', 'Nueva característica', '新機能'),
    };
    saveQuoteSection({ ...quoteSection, features: [...quoteSection.features, newFeature] });
    markDirty('quoteSection');
  };

  const removeFeature = (id: string) => {
    if (quoteSection.features.length <= 1) {
      toast.warning('At least one feature is required');
      return;
    }
    saveQuoteSection({
      ...quoteSection,
      features: quoteSection.features.filter((f) => f.id !== id),
    });
    markDirty('quoteSection');
  };

  const moveFeature = (id: string, dir: -1 | 1) => {
    const idx = quoteSection.features.findIndex((f) => f.id === id);
    if (idx === -1) return;
    const newIdx = idx + dir;
    if (newIdx < 0 || newIdx >= quoteSection.features.length) return;
    const next = [...quoteSection.features];
    [next[idx], next[newIdx]] = [next[newIdx], next[idx]];
    saveQuoteSection({ ...quoteSection, features: next });
    markDirty('quoteSection');
  };

  const handlePageTranslateAll = async () => {
    const tasks: { label: string; value: I18nText }[] = [];
    tasks.push({ label: 'Title', value: quoteSection.title });
    tasks.push({ label: 'Subtitle', value: quoteSection.subtitle });
    quoteSection.features.forEach((f, i) => {
      tasks.push({ label: `Feature ${i + 1} text`, value: f.text });
    });

    const toTranslate = tasks.filter((t) => t.value.en.trim());
    if (toTranslate.length === 0) {
      toast.warning('No English content to translate');
      return;
    }

    setPageTranslating(true);
    setPageProgress({ current: 0, total: toTranslate.length });
    try {
      const results = await batchTranslateI18n(toTranslate, (cur, total) => {
        setPageProgress({ current: cur, total });
      });

      let resultIdx = 0;
      let nextTitle = quoteSection.title;
      let nextSubtitle = quoteSection.subtitle;
      let nextFeatures = [...quoteSection.features];
      let changed = false;

      // Title
      if (quoteSection.title.en.trim()) {
        const r = results[resultIdx];
        if (r && !r.skipped && r.success) {
          nextTitle = r.value;
          changed = true;
        }
        resultIdx++;
      }
      // Subtitle
      if (quoteSection.subtitle.en.trim()) {
        const r = results[resultIdx];
        if (r && !r.skipped && r.success) {
          nextSubtitle = r.value;
          changed = true;
        }
        resultIdx++;
      }
      // Features
      for (let i = 0; i < nextFeatures.length; i++) {
        if (nextFeatures[i].text.en.trim()) {
          const r = results[resultIdx];
          if (r && !r.skipped && r.success) {
            nextFeatures[i] = { ...nextFeatures[i], text: r.value };
            changed = true;
          }
          resultIdx++;
        }
      }

      if (changed) {
        saveQuoteSection({
          ...quoteSection,
          title: nextTitle,
          subtitle: nextSubtitle,
          features: nextFeatures,
        });
        markDirty('quoteSection');
      }

      const successCount = results.filter((r) => r.success).length;
      const failed = results.filter((r) => !r.success && !r.skipped);
      if (failed.length > 0) {
        toast.warning(`Translated ${successCount}/${results.length}. ${failed.length} failed`);
      } else {
        toast.success(`Translation completed: ${successCount} fields`);
      }
    } catch {
      toast.error('Translation failed');
    } finally {
      setPageTranslating(false);
      setPageProgress({ current: 0, total: 0 });
    }
  };

  const handleSync = async () => {
    const config = getGithubApiConfig();
    if (!config) {
      toast.error('GitHub sync not configured');
      return;
    }
    // 用最新 localStorage 数据
    let data: unknown = null;
    try {
      const saved = localStorage.getItem('__app_ledlight_quote_section_v1');
      if (saved) {
        const parsed = JSON.parse(saved);
        data = parsed.data ?? null;
      }
    } catch {
      // ignore
    }
    await syncJsonFile(config, 'data/quote-section.json', data, 'Update quote section');
  };

  const langTabs: Array<{ value: Lang; label: string }> = [
    { value: 'en', label: 'EN' },
    { value: 'zh', label: '中文' },
    { value: 'es', label: 'ES' },
    { value: 'ja', label: '日本語' },
  ];

  return (
    <div className="space-y-4">
      <PageBreadcrumb
        firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }}
        items={[{ label: adminT('admin.quoteSection') }]}
      />

      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-foreground">{adminT('admin.quoteSection')}</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Manage the &ldquo;Get a Free Quote&rdquo; section on homepage
          </p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <SyncStatusBadge status={syncStatus} />
          <Button
            variant="outline"
            size="sm"
            onClick={handleSync}
            disabled={syncStatus === 'syncing'}
            className="text-xs h-9"
          >
            <Upload className="size-3.5 mr-1.5" />
            Sync to GitHub
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={handlePageTranslateAll}
            disabled={pageTranslating}
            className="text-xs h-9"
          >
            {pageTranslating ? (
              <>
                <Loader2 className="size-3.5 mr-1.5 animate-spin" />
                Translating {pageProgress.current}/{pageProgress.total}...
              </>
            ) : (
              <>
                <RefreshCw className="size-3.5 mr-1.5" />
                Translate All
              </>
            )}
          </Button>
        </div>
      </div>

      {/* 总开关 */}
      <Card className="border-primary/20 bg-primary/5">
        <CardContent className="py-4 px-5 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
          <div>
            <h3 className="text-sm font-semibold text-foreground flex items-center gap-2">
              <Eye className="size-4 text-primary" />
              Show Quote Section on Homepage
            </h3>
            <p className="text-xs text-muted-foreground mt-1">
              Toggle the entire quote section display on the homepage.
            </p>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-xs text-muted-foreground">
              {quoteSection.showOnHomepage ? 'Showing on homepage' : 'Hidden on homepage'}
            </span>
            <Switch
              checked={quoteSection.showOnHomepage}
              onCheckedChange={(val) => {
                setShowOnHomepage(val);
                markDirty('quoteSection');
                toast.success(val ? 'Quote section will show on homepage' : 'Quote section hidden on homepage');
              }}
            />
          </div>
        </CardContent>
      </Card>

      {/* 内容编辑 */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base">Section Content</CardTitle>
          <CardDescription>
            Edit title, subtitle and feature points. Use language tabs to switch between languages.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          <Tabs value={activeLang} onValueChange={(v) => setActiveLang(v as Lang)}>
            <TabsList className="mb-4">
              {langTabs.map((l) => (
                <TabsTrigger key={l.value} value={l.value}>
                  {l.label}
                </TabsTrigger>
              ))}
            </TabsList>

            {langTabs.map((l) => (
              <TabsContent key={l.value} value={l.value} className="space-y-5">
                <div>
                  <label className="text-xs font-medium text-foreground mb-1.5 block">
                    Title ({l.label})
                  </label>
                  <Input
                    value={quoteSection.title[l.value]}
                    onChange={(e) => handleTitleChange(l.value, e.target.value)}
                    placeholder="Get a Free Quote"
                  />
                </div>
                <div>
                  <label className="text-xs font-medium text-foreground mb-1.5 block">
                    Subtitle ({l.label})
                  </label>
                  <Textarea
                    value={quoteSection.subtitle[l.value]}
                    onChange={(e) => handleSubtitleChange(l.value, e.target.value)}
                    placeholder="Tell us your requirements and we will respond within 12 hours."
                    rows={2}
                  />
                </div>
              </TabsContent>
            ))}
          </Tabs>
        </CardContent>
      </Card>

      {/* 特点列表 */}
      <Card>
        <CardHeader className="pb-3 flex flex-row items-center justify-between">
          <div>
            <CardTitle className="text-base">Features ({quoteSection.features.length})</CardTitle>
            <CardDescription>Icon + text feature points displayed next to the quote form</CardDescription>
          </div>
          <Button size="sm" onClick={addFeature} className="h-8">
            Add Feature
          </Button>
        </CardHeader>
        <CardContent className="p-0">
          <div className="w-full overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-border">
                  <th className="text-left text-xs font-medium text-muted-foreground px-4 py-3 w-16 whitespace-nowrap">
                    Order
                  </th>
                  <th className="text-left text-xs font-medium text-muted-foreground px-4 py-3 w-24 whitespace-nowrap">
                    Icon
                  </th>
                  <th className="text-left text-xs font-medium text-muted-foreground px-4 py-3 whitespace-nowrap">
                    Text (EN)
                  </th>
                  <th className="text-left text-xs font-medium text-muted-foreground px-4 py-3 w-28 whitespace-nowrap">
                    Language
                  </th>
                  <th className="text-right text-xs font-medium text-muted-foreground px-4 py-3 w-24 whitespace-nowrap">
                    Actions
                  </th>
                </tr>
              </thead>
              <tbody>
                {quoteSection.features.map((feature, idx) => {
                  const Icon = getIconComponent(feature.icon);
                  return (
                    <tr key={feature.id} className="border-b border-border/60 hover:bg-muted/20">
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-1">
                          <GripVertical className="size-3.5 text-muted-foreground" />
                          <span className="text-xs text-muted-foreground tabular-nums">{idx + 1}</span>
                        </div>
                      </td>
                      <td className="px-4 py-3">
                        <div className="w-9 h-9 rounded-md bg-primary/10 flex items-center justify-center">
                          <Icon className="size-4 text-primary" />
                        </div>
                      </td>
                      <td className="px-4 py-3 font-medium">
                        {feature.text.en}
                      </td>
                      <td className="px-4 py-3">
                        <Select
                          value={activeLang}
                          onValueChange={(v) => setActiveLang(v as Lang)}
                        >
                          <SelectTrigger className="h-8 text-xs w-24">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            {langTabs.map((l) => (
                              <SelectItem key={l.value} value={l.value} className="text-xs">
                                {l.label}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </td>
                      <td className="px-4 py-3 text-right">
                        <div className="flex items-center justify-end gap-1">
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => moveFeature(feature.id, -1)}
                            disabled={idx === 0}
                            className="h-7 w-7"
                            title="Move up"
                          >
                            <span className="text-xs">↑</span>
                          </Button>
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => moveFeature(feature.id, 1)}
                            disabled={idx === quoteSection.features.length - 1}
                            className="h-7 w-7"
                            title="Move down"
                          >
                            <span className="text-xs">↓</span>
                          </Button>
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => removeFeature(feature.id)}
                            className="h-7 w-7 text-destructive"
                            title="Delete"
                          >
                            <Edit2 className="size-3.5" />
                          </Button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      {/* 特点逐个编辑（用 Tabs 切语言） */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base">Edit Feature Texts</CardTitle>
          <CardDescription>Edit each feature&apos;s multi-language text and select its icon.</CardDescription>
        </CardHeader>
        <CardContent className="space-y-5">
          {quoteSection.features.map((feature, idx) => (
            <div key={feature.id} className="space-y-3 p-4 rounded-lg border border-border/40 bg-muted/10">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <span className="text-xs font-semibold text-muted-foreground">
                    Feature {idx + 1}
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <label className="text-xs text-muted-foreground">Icon:</label>
                  <Select
                    value={feature.icon}
                    onValueChange={(val) => handleFeatureIconChange(feature.id, val)}
                  >
                    <SelectTrigger className="h-8 w-40 text-xs">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {ICON_OPTIONS.map((opt) => (
                        <SelectItem key={opt.value} value={opt.value} className="text-xs">
                          <div className="flex items-center gap-2">
                            <opt.Icon className="size-3.5" />
                            <span>{opt.label}</span>
                          </div>
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <Tabs value={activeLang} onValueChange={(v) => setActiveLang(v as Lang)}>
                <TabsList className="mb-2">
                  {langTabs.map((l) => (
                    <TabsTrigger key={l.value} value={l.value}>
                      {l.label}
                    </TabsTrigger>
                  ))}
                </TabsList>
                {langTabs.map((l) => (
                  <TabsContent key={l.value} value={l.value}>
                    <Input
                      value={feature.text[l.value]}
                      onChange={(e) => handleFeatureTextChange(feature.id, l.value, e.target.value)}
                      placeholder={`Feature text (${l.label})`}
                    />
                  </TabsContent>
                ))}
              </Tabs>
            </div>
          ))}
        </CardContent>
      </Card>
    </div>
  );
}
